import React, { useState, useEffect } from 'react';
import { useParams } from 'react-router-dom';
import { getLatestMovies } from '../api/tmdb';

function MovieDetail() {
  const { id } = useParams();
  const [movie, setMovie] = useState(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const fetchMovieDetail = async () => {
      setLoading(true);
      const movies = await getLatestMovies();
      const foundMovie = movies.find((m) => String(m.id) === String(id)) || movies[0];
      setMovie(foundMovie);
      setLoading(false);
    };
    fetchMovieDetail();
  }, [id]);

  if (loading || !movie) {
    return (
      <div className="w-full min-h-screen bg-[#0b090e] flex items-center justify-center text-white">
        <p className="text-sm font-bold animate-pulse text-purple-400">영화 정보를 불러오는 중...</p>
      </div>
    );
  }

  const posterUrl = movie.poster_path 
    ? `https://image.tmdb.org/t/p/w500${movie.poster_path}` 
    : "https://via.placeholder.com/300x450?text=No+Image";

  const backdropUrl = movie.backdrop_path 
    ? `https://image.tmdb.org/t/p/original${movie.backdrop_path}` 
    : posterUrl;

  return (
    <div className="w-full min-h-screen bg-[#0b090e] text-white flex flex-col items-center pb-20">
      
      {/* 상단 히어로 백드롭 영역 */}
      <div 
        className="w-full relative h-[420px] flex flex-col justify-end p-8 bg-cover bg-center" 
        style={{ backgroundImage: `url(${backdropUrl})` }}
      >
        <div className="absolute inset-0 bg-gradient-to-t from-[#0b090e] via-[#0b090e]/70 to-black/50" />
        <div className="relative z-10 max-w-5xl w-full mx-auto space-y-2">
          <h1 className="text-3xl md:text-5xl font-black tracking-tight drop-shadow-lg text-white">
            {movie.title || movie.name}
          </h1>
          <p className="text-xs text-zinc-300 font-bold tracking-wide">
            {movie.release_date ? movie.release_date.split('-')[0] : '2026'} &bull; 13+ &bull; 1h 51m &bull; Language: {movie.original_language?.toUpperCase() || 'EN'}
          </p>
        </div>
      </div>

      {/* 중앙 본문 정보 영역 (레퍼런스 스타일의 세련된 카드 박스 조합) */}
      <div className="max-w-5xl w-full px-6 -mt-8 relative z-20 grid grid-cols-1 md:grid-cols-3 gap-8 items-start">
        
        {/* 포스터 박스 */}
        <div className="w-48 h-72 rounded-2xl overflow-hidden shadow-[0_20px_40px_rgba(0,0,0,0.8)] border border-white/15 mx-auto md:mx-0 bg-zinc-900 flex-shrink-0 ring-4 ring-purple-500/20">
          <img src={posterUrl} alt={movie.title} className="w-full h-full object-cover" />
        </div>

        {/* 상세 설명 및 정보 박스 (내용이 없을 때도 꽉 차 보이도록 구성 보완) */}
        <div className="md:col-span-2 space-y-5 bg-[#181124]/90 backdrop-blur-md p-7 rounded-2xl border border-purple-500/30 shadow-2xl relative overflow-hidden">
          
          {/* 빛 번짐 포인트 */}
          <div className="absolute top-0 right-0 w-48 h-48 bg-purple-600/10 rounded-full blur-2xl pointer-events-none" />

          <div>
            <span className="text-[11px] text-purple-400 font-extrabold uppercase tracking-widest block mb-1">Overview & Info</span>
            <h3 className="text-lg font-black text-white">Directed by TMDB Creator</h3>
          </div>

          <p className="text-xs text-zinc-300 leading-relaxed font-medium">
            {movie.overview || "메가박스에서 제안하는 특별한 시네마틱 감성과 함께 감상해보세요. 몰입감 넘치는 사운드와 화려한 영상미를 선사합니다."}
          </p>

          <div className="flex gap-2 pt-1 flex-wrap">
            <span className="text-[10px] font-bold px-3.5 py-1 rounded-full border border-purple-400/40 text-purple-200 bg-purple-950/50">
              Drama
            </span>
            <span className="text-[10px] font-bold px-3.5 py-1 rounded-full border border-purple-400/40 text-purple-200 bg-purple-950/50">
              Masterpiece
            </span>
            <span className="text-[10px] font-bold px-3.5 py-1 rounded-full border border-purple-400/40 text-purple-200 bg-purple-950/50">
              Megabox Pick
            </span>
          </div>

          <div className="flex items-center justify-between pt-4 border-t border-white/10">
            <span className="text-xs font-bold text-zinc-400">Personal Rating Score</span>
            <div className="w-12 h-12 rounded-full border-2 border-yellow-400 flex items-center justify-center text-yellow-400 font-black text-sm shadow-[0_0_15px_rgba(250,204,21,0.4)] bg-yellow-400/10">
              {movie.vote_average ? movie.vote_average.toFixed(1) : '9.0'}
            </div>
          </div>
        </div>

      </div>

      {/* 갤러리 영역 */}
      <div className="max-w-5xl w-full px-6 mt-14">
        <h3 className="text-sm font-black tracking-widest text-purple-300 mb-4 uppercase">Gallery</h3>
        <div className="grid grid-cols-1 md:grid-cols-3 gap-5">
          <div className="h-40 rounded-xl overflow-hidden border border-white/15 shadow-xl bg-zinc-900 group">
            <img src={backdropUrl} alt="gallery 1" className="w-full h-full object-cover group-hover:scale-105 transition duration-500" />
          </div>
          <div className="h-40 rounded-xl overflow-hidden border border-white/15 shadow-xl bg-zinc-900 group">
            <img src={posterUrl} alt="gallery 2" className="w-full h-full object-cover group-hover:scale-105 transition duration-500" />
          </div>
          <div className="h-40 rounded-xl overflow-hidden border border-white/15 shadow-xl bg-zinc-900 group">
            <img src={backdropUrl} alt="gallery 3" className="w-full h-full object-cover group-hover:scale-105 transition duration-500" />
          </div>
        </div>
      </div>

    </div>
  );
}

export default MovieDetail;
